LOCALE_TEST_CLASS_NAME_REGEX = re.compile(
    r"^Test(?P<language>[A-Z][a-z]{1,2})(?P<region>[A-Z][a-z])$",
)


@pytest.fixture(scope="class", autouse=True)
def _class_locale_faker(request):
